  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueAttachment[]> {

const BYTES_PER_MB = 1024 * 1024;

/** Megabytes an upload is charged: each file rounds up to a whole megabyte. */
function chargedMegabytes(sizeBytes: number): number {
  return Math.ceil(sizeBytes / BYTES_PER_MB);
}

